import{_ as r,C as t,o as i,c as s,E as a,a2 as l}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/continuity-20260914/clear-continuation.figure.en.png",b=JSON.parse('{"title":"Why Can an Empty History Still Reference an Old Conversation?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Why Can an Empty History Still Reference an Old Conversation?","date":"2026-09-14","published_date":"2026-09-14","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Why Can an Empty History Still Reference an Old Conversation?","summary":"The history is empty, but the program may still hold a bookmark to the old conversation. An experiment between deletion and acknowledgement follows what happens next.","cover":"/assets/continuity-20260914/clear-continuation.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments on pinned sources; no live cloud validation","pageClass":"continuity-contracts-article"},"headers":[],"relativePath":"en/engineering/2026-09-14-clear-continuation.md","filePath":"en/engineering/2026-09-14-clear-continuation.md","lastUpdated":1789364063000}'),d={name:"en/engineering/2026-09-14-clear-continuation.md"};function h(p,e,u,m,g,f){const n=t("ArticleCover"),o=t("ArticleTableScroll");return i(),s("div",null,[a(n,{image:"/assets/continuity-20260914/clear-continuation.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"Why Can an Empty History Still Reference an Old Conversation?",summary:"The history is empty, but the program may still hold a bookmark to the old conversation. An experiment between deletion and acknowledgement follows what happens next.",version:"2026-09-14",languageHref:"/zh/engineering/2026-09-14-clear-continuation",languageLabel:"中文"}),a(o,{language:"en"}),e[0]||(e[0]=l('<h1 id="why-can-an-empty-history-still-reference-an-old-conversation" tabindex="-1">Why Can an Empty History Still Reference an Old Conversation? <a class="header-anchor" href="#why-can-an-empty-history-still-reference-an-old-conversation" aria-label="Permalink to &quot;Why Can an Empty History Still Reference an Old Conversation?&quot;">​</a></h1><p>You clear a session, and its history becomes empty. That feels like a fresh start.</p><p>Yet when the program prepares its next operation, it may still pick up an old identifier and continue along the previous conversation.</p><p>The problem sits outside the history list. In the OpenAI Agents SDK—a toolkit for building AI assistants—we studied session-management code that cleared history but left references that later operations could still read. This is a story about those references, not evidence of an AI “secretly remembering.”</p><p>To understand it, first consider what a conversation leaves behind besides its text.</p><h2 id="the-content-is-gone-the-bookmark-remains" tabindex="-1">The content is gone; the bookmark remains <a class="header-anchor" href="#the-content-is-gone-the-bookmark-remains" aria-label="Permalink to &quot;The content is gone; the bookmark remains&quot;">​</a></h2><p>A program does not always have to resend every item to continue a conversation. It can also use a response identifier to continue along an existing response chain.</p><p>Think of that identifier as a bookmark held by the program. The history list holds conversation content; the bookmark tells a later operation where to reconnect. Clearing a list does not automatically update every place holding a bookmark.</p><p>In the code we tested, that later operation was context compaction: preparing a shorter representation of a long conversation for subsequent use. The session component could provide current content or continue from an old response ID. As long as it could still select that ID, an empty list did not establish that the old connection was severed.</p><p><a href="https://github.com/openai/openai-agents-python/pull/5000" target="_blank" rel="noreferrer">Candidate fix #5000</a>, proposed by contributor <a href="https://github.com/sbguangha" target="_blank" rel="noreferrer">sbguangha</a> in the OpenAI Agents SDK, addresses two omissions: the current response ID and the most recent response ID not yet stored in history. These are references that guide continuation, not two additional copies of the entire conversation. This fix and its tests prompted our clearing comparison.</p><p>We are developing CodeFlowMu, a system for collaboration among AI assistants, and need to consider which old state is actually used when work continues or context is rebuilt. What made this source especially interesting was that specific references were overlooked despite an existing lock and state-change tracking. It raised a testable distinction: do preventing conflicting operations and invalidating obsolete references require separate checks? The supplied failure cases let us investigate that question experimentally. The implementations differ, so this does not establish the same defect in our system.</p><p>Clearing them along with the history sounds straightforward. But what should happen when clearing fails?</p><h2 id="the-difficult-moment-deleted-but-not-acknowledged" tabindex="-1">The difficult moment: deleted, but not acknowledged <a class="header-anchor" href="#the-difficult-moment-deleted-but-not-acknowledged" aria-label="Permalink to &quot;The difficult moment: deleted, but not acknowledged&quot;">​</a></h2><p>Deletion becoming effective and the caller receiving confirmation can happen at different moments.</p><p>We tested two cases: the local database commits deletion, then the operation is cancelled before returning; or deletion commits, then its acknowledgement raises an error.</p><p>The caller sees failure, but the database history really is empty. If the program interprets failure as “nothing happened” and retains the old IDs, content and references diverge.</p><p>To expose that gap, the tests used a real temporary SQLite database—a database that can store data in a local file. They paused after the deletion commit but before the operation returned, then injected cancellation or an error. We checked more than empty history: whether later operations could reuse the old reference, whether the lock was released, and whether new content could still be written.</p><h2 id="put-the-old-method-back-and-the-problem-returns" tabindex="-1">Put the old method back, and the problem returns <a class="header-anchor" href="#put-the-old-method-back-and-the-problem-returns" aria-label="Permalink to &quot;Put the old method back, and the problem returns&quot;">​</a></h2><p>We pinned the complete SDK and original upstream tests, ran the candidate, then replaced only its clear method with the predecessor&#39;s implementation. Keeping the rest unchanged helps isolate the effect of clearing itself.</p><p>The five checks produced these results:</p><table tabindex="0"><thead><tr><th>Question under test</th><th>Old clear method</th><th>Candidate fix</th></tr></thead><tbody><tr><td>Does normal clearing invalidate the old response reference?</td><td>Fails</td><td>Passes</td></tr><tr><td>Is the old reference invalidated after cancellation following deletion commit?</td><td>Fails</td><td>Passes</td></tr><tr><td>Is it invalidated when acknowledgement raises after deletion commit?</td><td>Fails</td><td>Passes</td></tr><tr><td>Does automatic compaction use current input after clearing?</td><td>Fails</td><td>Passes</td></tr><tr><td>Does clearing wait for in-flight compaction and leave empty history?</td><td>Passes</td><td>Passes</td></tr></tbody></table><p>The old method failed four checks and passed one; the candidate passed all five. The last row was an existing concurrency check. It helps rule out an overly broad explanation: this was not simply an implementation with no concurrency protection.</p><p><img src="'+c+'" alt="Cleared history and invalidated continuation references"></p><p><em>Figure 1. Empty history and invalidated references require separate checks. Source: this study&#39;s runs/sdk.json and original test logs; database commits were real local operations, while the remote compact endpoint was a test double.</em></p><p>That observation boundary matters. We inspected how the local component prepared subsequent requests without contacting the real OpenAI service. The experiment shows that an old reference path remained available, not that a remote server recovered deleted data.</p><h2 id="another-protection-does-not-automatically-fix-an-omission" tabindex="-1">Another protection does not automatically fix an omission <a class="header-anchor" href="#another-protection-does-not-automatically-fix-an-omission" aria-label="Permalink to &quot;Another protection does not automatically fix an omission&quot;">​</a></h2><p>The SDK already had a lock to coordinate concurrent operations and an internal generation counter to track state changes. Each has a purpose. Neither automatically clears every stored response ID.</p><p>The fix did not introduce another generation mechanism. It invalidated the two omitted response references in both successful and exceptional cleanup paths.</p><p>That suggests a useful way to investigate clearing: work backward from the next operation. Where does it get its content, identifiers, or deferred work? What remains in each location after normal clearing, cancellation, and failed acknowledgement?</p><p>For developers, those questions follow the actual use of the system more closely than an assertion that history contains zero rows. For users, they explain why an empty interface alone cannot reveal everything the system will use next.</p><details><summary>Further reading: the right conversation, but the wrong task?</summary><p>Another source was <a href="https://github.com/paperclipai/paperclip/pull/13345" target="_blank" rel="noreferrer">Paperclip #13345</a>, proposed by contributor <a href="https://github.com/cryppadotta" target="_blank" rel="noreferrer">cryppadotta</a>. Paperclip organizes AI assistants performing tasks. This change addresses a session resuming while its invocation omits an updated task description, allowing an old comment to become the objective again. It prompted us to inspect what the next call actually receives.</p><p>We checked seven before/after inputs to the original task-brief selector. With normalized wake inputs, two ordinary-resume cases changed from selecting only a short task identifier to including the current full brief. Fresh-task, assignment, recovery, and other controls retained their respective behavior. This covered the selector and helpers, not database objective selection or a real resumed AI session.</p><p>The required actions differ: one must sever an old connection; the other must deliver new instructions into a conversation that remains valid. Both suggest following the next call to inspect what it actually receives.</p></details><p>An acceptance check after clearing can go one step further: <strong>where will the next operation start?</strong> Following that question reveals relationships an empty history list cannot show. It is a research lesson from these experiments; it has not established a corresponding CodeFlowMu defect or initiated development. The comparison also raises a more specific question: after these two references are invalidated, could an already queued retry or delayed operation still carry an old ID? Our five checks did not cover those paths. Answering it would require arranging such pending work before clearing, then inspecting what the actual subsequent invocation uses. That is a testable follow-up, not another fault already discovered.</p><p><strong>Scope and reproduction.</strong> The fix was still open when read for this study. These results concern pinned candidate source, not every released version. Remote calls were mocked; SQLite deletion commits happened locally. Cross-process restarts, remote erasure, and general authorization revocation were not tested. The five SDK comparisons, seven Paperclip inputs, fixed versions, and failing logs are in the <a href="./../research/evidence/2026-09-14-continuity-contracts">evidence package</a>, maintained in the <a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">research repository</a>.</p><p>When you click “clear,” what do you expect to disappear: the visible history, the context used by the next response, or both? Does the tool explain that clearly? If you build session systems, what counterexamples or tests would you add for work queued before clearing but executed afterward?</p>',34))])}const w=r(d,[["render",h]]);export{b as __pageData,w as default};
